from AlgorithmImports import *
from datetime import timedelta, time
from collections import deque


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.blocked_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy_symbol, consolidator)

    def OnData(self, slice: Slice):
        self.current_slice = slice
        today = self.Time.date()

        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing(today)
        self.HandleTimeStop(today)
        self.HandleProfitTarget(slice)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if bar.Symbol != self.spy_symbol:
            return

        self.fast_window.append(bar.Close)
        self.slow_window.append(bar.Close)

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            return

        fast = sum(list(self.fast_window)[-5:]) / 5.0
        slow = sum(self.slow_window) / 20.0

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = bar.EndTime.astimezone(self.TimeZone)
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if bullish_cross and eligible_time:
            self.TryEnter(bar.Close)

    def TryEnter(self, spy_price: float):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        ):
            return

        if self.current_slice is None or not self.current_slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        chains = [
            chain for chain in self.current_slice.OptionChains
            if chain.Symbol == self.option_symbol
        ]

        if not chains:
            self.Debug("Skipped entry: no SPY option chain.")
            return

        contracts = []
        for chain in chains:
            contracts.extend(list(chain.Contracts.Values))

        minimum_expiry = today + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiration {} strike {:.2f}".format(
                selected.Symbol, selected.Expiry.date(), selected.Strike
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_option, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        message = (order_event.Message or "").lower()
        if "assignment" in message or "exercise" in message:
            self.blocked_entry_date = self.Time.date()
            self.Debug("Unexpected exercise or assignment handling: {}".format(
                order_event.Message
            ))
            if self.Portfolio[self.spy_symbol].Quantity != 0:
                self.MarketOrder(
                    self.spy_symbol,
                    -self.Portfolio[self.spy_symbol].Quantity
                )

    def HandleProfitTarget(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None:
            return

        contract = None
        for chain in slice.OptionChains:
            if self.held_option in chain.Contracts:
                contract = chain.Contracts[self.held_option]
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("profit target")

    def HandleTimeStop(self, today):
        if self.held_option is None or self.exit_ticket is not None:
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        prior_trading_day = self.PreviousTradingDay(expiry)

        if today == prior_trading_day and self.Time.time() >= time(15, 45):
            self.SubmitExit("time stop")

    def HandleExpirationProcessing(self, today):
        if self.held_option is None:
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        if today >= expiry:
            self.blocked_entry_date = today
            if self.exit_ticket is None:
                self.SubmitExit("expiration processing")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None:
            return

        for ticket in self.Transactions.GetOpenOrders(self.held_option):
            if ticket.OrderId != (self.entry_ticket.OrderId if self.entry_ticket else -1):
                self.Transactions.CancelOrder(ticket.OrderId)

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -quantity,
                tag=reason
            )
            self.Debug("Exit submitted: {} ({})".format(self.held_option, reason))

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity != 0:
            self.blocked_entry_date = self.Time.date()
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.MarketOrder(self.spy_symbol, -quantity)

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate
