from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(lambda u: u.IncludeWeeklys()
                              .Strikes(-200, 200)
                              .Expiration(timedelta(days=0), timedelta(days=730)))

        self.fast_values = RollingWindow[float](5)
        self.slow_values = RollingWindow[float](20)

        self.current_bucket_start = None
        self.current_bucket = {}
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_expiration_day = None

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing(today)

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            self._evaluate_exit(slice)
        elif self.held_symbol is not None and not self.Portfolio[self.held_symbol].Invested:
            self.held_symbol = None
            self.entry_price = None
            self.exit_ticket = None

        if self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        ):
            return

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        self._process_spy_minute(spy_bar, slice)

    def _process_spy_minute(self, bar: TradeBar, slice: Slice):
        local_end = bar.EndTime.astimezone(self.TimeZone).replace(tzinfo=None)
        session_start = time(9, 30)
        session_end = time(16, 0)

        if not (session_start < local_end.time() <= session_end):
            return

        bucket_minute = ((local_end.minute - 30) // 5) * 5 + 30
        bucket_start = local_end.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start

        if bucket_start != self.current_bucket_start:
            self._complete_five_minute_bar(slice)
            self.current_bucket = {}
            self.current_bucket_start = bucket_start

        self.current_bucket[local_end] = bar

        if local_end.time() == time(15, 55):
            self._complete_five_minute_bar(slice)
            self.current_bucket = {}
            self.current_bucket_start = None

    def _complete_five_minute_bar(self, slice: Slice):
        if self.current_bucket_start is None:
            return

        expected = [
            self.current_bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if any(t not in self.current_bucket for t in expected):
            return

        close = self.current_bucket[expected[-1]].Close
        previous_fast = self.fast_values[0] if self.fast_values.IsReady else None
        previous_slow = self.slow_values[0] if self.slow_values.IsReady else None

        self.fast_values.Add(close)
        self.slow_values.Add(close)

        if not (self.fast_values.IsReady and self.slow_values.IsReady):
            return

        current_fast = sum(self.fast_values[i] for i in range(5)) / 5.0
        current_slow = sum(self.slow_values[i] for i in range(20)) / 20.0

        bar_end = self.current_bucket_start + timedelta(minutes=5)
        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if previous_fast is None or previous_slow is None:
            return

        previous_fast = sum(self.fast_values[i + 1] for i in range(5)) / 5.0
        previous_slow = sum(self.slow_values[i + 1] for i in range(20)) / 20.0

        bullish = previous_fast <= previous_slow and current_fast > current_slow
        if bullish:
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        if self.held_symbol is not None:
            return

        if self.no_entry_expiration_day == self.Time.date():
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        algorithm_date = self.Time.date()
        eligible = [
            c for c in chain
            if c.Expiry.date() >= algorithm_date + timedelta(days=7)
        ]

        if not eligible:
            self.Debug("Skipped entry: no expiration at least seven calendar days out.")
            return

        expiration = min(c.Expiry.date() for c in eligible)
        spy_price = self.Securities[self.spy].Price
        minimum_strike = 1.01 * spy_price

        candidates = [
            c for c in eligible
            if c.Expiry.date() == expiration
            and c.Right == OptionRight.Call
            and c.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = sorted(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def _evaluate_exit(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        security = slice.OptionChains
        quote = slice.QuoteBars.get(self.held_symbol)
        now = self.Time

        profit_target = False
        if quote is not None:
            bid = quote.Bid.Close
            ask = quote.Ask.Close
            if bid > 0 and ask > 0:
                profit_target = (bid + ask) / 2.0 >= 1.5 * self.entry_price

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        previous_day = expiry - timedelta(days=1)
        time_stop = (
            now.date() == previous_day and
            now.time() >= time(15, 45)
        )

        if profit_target or time_stop:
            reason = "profit target" if profit_target else "time stop"
            self._submit_exit(reason)

    def _submit_exit(self, reason):
        if self.exit_ticket is not None and self.exit_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            return

        if self.held_symbol is None:
            return

        if self.entry_ticket is not None:
            self.entry_ticket = None

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(self.held_symbol, quantity)
            self.Debug(f"Exit submitted ({reason}): {self.held_symbol}")

    def _handle_expiration_processing(self, today):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if today >= expiry:
            self.no_entry_expiration_day = today
            self._submit_exit("expiration processing")

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Invested:
            self.Debug("Unexpected exercise or assignment: liquidating SPY position.")
            self.MarketOrder(self.spy, -holding.Quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_symbol}, price {self.entry_price}"
                )
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}, price {order_event.FillPrice}")
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None

